import React, { useEffect, useState } from "react";
import axios from "axios";
import sorsuLogo from "../assets/sorsu-logo.png";

export default function Vote() {
  const [candidates, setCandidates] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchCandidates();
  }, []);

  const fetchCandidates = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const grouped = candidates.reduce((acc, candidate) => {
    if (!acc[candidate.position]) {
      acc[candidate.position] = [];
    }
    acc[candidate.position].push(candidate);
    return acc;
  }, {});

  const handleSelect = (position, candidateId) => {
    setSelected((prev) => ({
      ...prev,
      [position]: candidateId,
    }));
  };

  const allPositionsSelected =
    Object.keys(grouped).length > 0 &&
    Object.keys(grouped).every((pos) => selected[pos]);

  const handleCastVote = async () => {
    if (!allPositionsSelected) return;

    try {
      setLoading(true);
      await axios.post("http://localhost:5000/api/vote", {
        votes: selected,
      });
      alert("Vote successfully cast!");
    } catch (err) {
      alert("Error casting vote");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ background: "#f5f5f5", minHeight: "100vh" }}>
      {/* HEADER */}
      <div
        style={{
          background: "#b30000",
          color: "white",
          padding: "20px 40px",
          display: "flex",
          alignItems: "center",
        }}
      >
        <img
          src={sorsuLogo}
          alt="SorSU Logo"
          style={{ height: 60, marginRight: 20 }}
        />
        <div>
          <h2 style={{ margin: 0 }}>SorSU Online Voting</h2>
          <p style={{ margin: 0, fontSize: 14 }}>
            Official Student Election Portal
          </p>
        </div>
      </div>

      <div style={{ padding: 40 }}>
        {Object.keys(grouped).map((position) => (
          <div key={position} style={{ marginBottom: 60 }}>
            <h2 style={{ color: "#b30000", marginBottom: 20 }}>
              {position}
            </h2>

            <div
              style={{
                display: "flex",
                gap: 30,
                flexWrap: "wrap",
              }}
            >
              {grouped[position].map((candidate) => {
                const isSelected =
                  selected[position] === candidate._id;

                return (
                  <div
                    key={candidate._id}
                    onClick={() =>
                      handleSelect(position, candidate._id)
                    }
                    style={{
                      width: 300,
                      background: "white",
                      borderRadius: 15,
                      padding: 20,
                      cursor: "pointer",
                      transition: "0.3s",
                      boxShadow: isSelected
                        ? "0 0 0 3px #b30000"
                        : "0 5px 15px rgba(0,0,0,0.1)",
                      transform: isSelected
                        ? "scale(1.03)"
                        : "scale(1)",
                    }}
                  >
                    <img
                      src={`http://localhost:5000/uploads/${candidate.photo}`}
                      alt={candidate.name}
                      style={{
                        width: "100%",
                        height: 220,
                        objectFit: "cover",
                        borderRadius: 10,
                        border: "3px solid #b30000",
                      }}
                    />

                    <h3 style={{ marginTop: 15 }}>
                      {candidate.name}
                    </h3>
                    <p>{candidate.year}</p>
                    <p>Partylist: {candidate.partylist}</p>

                    {isSelected && (
                      <div
                        style={{
                          marginTop: 10,
                          color: "#b30000",
                          fontWeight: "bold",
                        }}
                      >
                        ✓ Selected
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* REVIEW BALLOT */}
        <div
          style={{
            background: "white",
            padding: 30,
            borderRadius: 15,
            boxShadow: "0 5px 20px rgba(0,0,0,0.1)",
            marginBottom: 30,
          }}
        >
          <h2 style={{ color: "#b30000" }}>Review Ballot</h2>

          {Object.keys(grouped).map((position) => {
            const candidateId = selected[position];
            const candidate = grouped[position].find(
              (c) => c._id === candidateId
            );

            return (
              <p key={position}>
                <strong>{position}:</strong>{" "}
                {candidate ? candidate.name : "Not selected"}
              </p>
            );
          })}
        </div>

        {/* CAST VOTE BUTTON */}
        <button
          onClick={handleCastVote}
          disabled={!allPositionsSelected || loading}
          style={{
            width: "100%",
            padding: 18,
            fontSize: 18,
            borderRadius: 10,
            border: "none",
            background: allPositionsSelected
              ? "#b30000"
              : "#ccc",
            color: "white",
            cursor: allPositionsSelected
              ? "pointer"
              : "not-allowed",
            transition: "0.3s",
          }}
        >
          {loading ? "Casting Vote..." : "Cast Vote"}
        </button>
      </div>
    </div>
  );
}
